import sqlite3, pathlib
# mevcut DB'de test
conn = sqlite3.connect('magaza.db')
cur = conn.cursor()
sorgu = pathlib.Path('cevap.sql').read_text()
cur.executescript(sorgu)
print('Tablolar:', cur.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall())
print('Satirlar:')
for r in cur.execute(sorgu):
    print(r)
conn.close()

# Farkli verili, ayni schema DB'de de calistir
conn2 = sqlite3.connect(':memory:')
c2 = conn2.cursor()
c2.executescript('''
CREATE TABLE musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
CREATE TABLE urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
CREATE TABLE siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL REFERENCES musteriler(id), tarih TEXT NOT NULL);
CREATE TABLE siparis_kalemleri (siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL, birim_fiyat REAL NOT NULL);
CREATE TABLE iadeler (id INTEGER PRIMARY KEY, siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL);
INSERT INTO musteriler VALUES (1,'Ali','Izmir','2024-01-01'),(2,'Veli','Ankara','2024-02-01');
INSERT INTO urunler VALUES (1,'Ekmek','Gida',10),(2,'Sut','Gida',15),(3,'Kalem','Kirtasiye',5),(4,'Defter','Kirtasiye',20),(5,'Lale','Cicek',30);
INSERT INTO siparisler VALUES (1,1,'2025-03-01'),(2,2,'2025-04-01'),(3,1,'2024-12-01');
INSERT INTO siparis_kalemleri VALUES (1,1,2,10),(1,2,1,15),(2,3,3,5),(2,5,2,30);
INSERT INTO iadeler VALUES (1,1,1,1);
''')
c2.executescript(sorgu)
print('--- Farkli DB ---')
for r in c2.execute(sorgu):
    print(r)
conn2.close()
